internal object DuaVi1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("Khi thức dậy", "Mọi lời ca ngợi kính dâng Allah, Đấng đã cho chúng tôi sống lại sau khi đã làm chúng tôi chết (ngủ), và sự trở về là về với Ngài.", "Đọc ngay khi thức dậy để tạ ơn Allah.", "Nabi ﷺ đọc lời này khi thức dậy — bắt đầu ngày mới với lòng biết ơn và nhớ đến đời sau."),
        "dua_leaving_home" to DuaText("Khi rời khỏi nhà", "Nhân danh Allah, tôi phó thác cho Allah, không có sức mạnh hay quyền năng nào ngoài Allah.", "Đọc khi ra khỏi nhà để cầu xin sự bảo vệ.", "Người đọc lời này được nói rằng: ngươi đã được hướng dẫn, được ban đủ, được bảo vệ — và Shaytan tránh xa người đó."),
        "dua_anxiety_distress" to DuaText("Lời cầu nguyện khi lo âu và buồn phiền", "Lạy Allah, con cầu xin Ngài che chở khỏi lo âu và buồn phiền, khỏi yếu đuối và lười biếng, khỏi keo kiệt và hèn nhát, khỏi gánh nặng nợ nần và sự áp bức của người khác.", "Khi lo âu, buồn phiền, nợ nần và khổ tâm.", "Nabi ﷺ thường đọc lời cầu nguyện này để cầu xin che chở khỏi buồn phiền, lười biếng và nợ nần."),
        "dua_sayyidul_istighfar" to DuaText("Lời cầu xin tha thứ tối thượng (Sayyidul Istighfar)", "Lạy Allah, Ngài là Thượng Đế của con, không có thần linh nào khác ngoài Ngài. Ngài đã tạo ra con và con là bề tôi của Ngài. Con giữ vững giao ước và lời hứa của Ngài hết khả năng của mình. Con cầu xin Ngài che chở khỏi điều xấu con đã làm. Con thừa nhận ân huệ của Ngài đối với con và thừa nhận tội lỗi của mình; xin Ngài tha thứ cho con, vì không ai tha thứ tội lỗi ngoài Ngài.", "Đọc vào buổi sáng và buổi tối — lời cầu xin tha thứ tốt nhất mà Nabi ﷺ đã dạy.", "Ai đọc lời này vào buổi tối với niềm tin vững chắc và qua đời đêm đó sẽ vào Thiên Đàng; cũng vậy nếu đọc vào buổi sáng."),
        "dua_parents" to DuaText("Lời cầu nguyện cho cha mẹ", "Lạy Thượng Đế của con, xin thương xót họ như họ đã nuôi dưỡng con khi con còn nhỏ.", "Lời cầu nguyện trong Kinh Qur'an để đáp lại công ơn nuôi dưỡng của cha mẹ.", "Allah đã ra lệnh về lời cầu nguyện này cho cha mẹ ngay trong Kinh Qur'an."),
        "dua_entering_mosque" to DuaText("Khi vào thánh đường", "Lạy Allah, xin mở cho con những cánh cửa lòng thương xót của Ngài.", "Đọc khi bước vào thánh đường bằng chân phải.", "Nabi ﷺ đã dạy lời cầu nguyện này khi vào thánh đường."),
        "dua_morning_asbahna" to DuaText("Lời tụng niệm buổi sáng", "Chúng tôi bước vào buổi sáng và vương quyền thuộc về Allah; mọi lời ca ngợi thuộc về Allah; không có thần linh nào khác ngoài Allah duy nhất, không có đối tác; vương quyền thuộc về Ngài, lời ca ngợi thuộc về Ngài, và Ngài có toàn năng trên mọi thứ.", "Lời tụng niệm được khuyến khích đọc vào buổi sáng.", "Bắt đầu ngày mới bằng việc thừa nhận quyền năng và sự duy nhất của Allah."),
        "dua_evening_amsayna" to DuaText("Lời tụng niệm buổi tối", "Chúng tôi bước vào buổi tối và vương quyền thuộc về Allah; mọi lời ca ngợi thuộc về Allah; không có thần linh nào khác ngoài Allah duy nhất, không có đối tác; vương quyền thuộc về Ngài, lời ca ngợi thuộc về Ngài, và Ngài có toàn năng trên mọi thứ.", "Lời tụng niệm được khuyến khích đọc vào buổi tối.", "Bắt đầu buổi tối bằng việc thừa nhận quyền năng và sự duy nhất của Allah."),
        "dua_before_sleep" to DuaText("Trước khi ngủ", "Nhân danh Ngài, lạy Allah, con chết đi và sống lại.", "Đọc sau khi nằm xuống để ngủ.", "Nabi ﷺ đọc lời này trước khi ngủ."),
        "dua_travel" to DuaText("Lời cầu nguyện khi đi đường", "Vinh quang thay Đấng đã ban cho chúng tôi phương tiện này để sử dụng, mà tự chúng tôi không thể chế ngự được; và quả thật chúng tôi sẽ trở về với Thượng Đế của chúng tôi.", "Đọc khi lên phương tiện đi lại sau khi đọc Takbir ba lần.", "Lời cầu nguyện đi đường được khuyến khích để được bảo vệ và ban phước."),
        "dua_ayatul_kursi" to DuaText("Ayatul Kursi sau khi hành lễ", "Allah, không có thần linh nào khác ngoài Ngài, Đấng Hằng Sống, Đấng Tự Hữu Hằng Còn. Ngài không buồn ngủ cũng không ngủ. Mọi thứ trên trời và dưới đất đều thuộc về Ngài. Ai có thể can thiệp trước Ngài nếu không được Ngài cho phép? Ngài biết những gì ở trước và sau họ. Họ không thể nắm bắt được điều gì trong kiến thức của Ngài ngoại trừ những gì Ngài muốn. Ngai vàng của Ngài bao trùm cả trời và đất, và việc gìn giữ chúng không làm Ngài mệt mỏi. Ngài là Đấng Tối Cao, Đấng Vĩ Đại.", "Đọc sau mỗi lễ nguyện bắt buộc và trước khi ngủ.", "Ai đọc lời này sau mỗi lễ nguyện bắt buộc thì chỉ có cái chết mới ngăn họ vào Thiên Đàng; ai đọc trước khi ngủ sẽ được bảo vệ đến sáng."),
        "dua_hasbunallah" to DuaText("Allah đã đủ cho chúng tôi", "Allah đã đủ cho chúng tôi và Ngài là Đấng Bảo Hộ tốt nhất.", "Đọc khi sợ hãi kẻ thù hoặc nguy hiểm lớn.", "Ibrahim đã nói lời này khi bị ném vào lửa, và Nabi ﷺ đã nói lời này lúc nguy hiểm."),
        "dua_entering_home" to DuaText("Khi vào nhà", "Nhân danh Allah chúng tôi vào, nhân danh Allah chúng tôi ra, và chúng tôi phó thác cho Thượng Đế của chúng tôi là Allah.", "Đọc khi vào nhà, nhắc đến tên Allah và chào hỏi.", "Với người nhớ đến Allah khi vào nhà và khi ăn, Shaytan nói: không có chỗ ở qua đêm hay bữa tối nào cho các ngươi."),
        "dua_yunus" to DuaText("Lời cầu nguyện của Nabi Yunus (bình an cho Người)", "Không có thần linh nào khác ngoài Ngài, Ngài thật trong sạch; quả thật con đã thuộc về những kẻ sai trái.", "Lời cầu nguyện của Nabi Yunus trong bụng cá — dành cho mọi khó khăn.", "Không một người Muslim nào cầu xin bằng lời này trong bất kỳ việc gì mà Allah không đáp lại."),
        "dua_karb" to DuaText("Lời cầu nguyện khi hoạn nạn nặng nề", "Không có thần linh nào khác ngoài Allah, Đấng Vĩ Đại, Đấng Khoan Dung. Không có thần linh nào khác ngoài Allah, Thượng Đế của Ngai Vàng vĩ đại. Không có thần linh nào khác ngoài Allah, Thượng Đế của các tầng trời, trái đất và Ngai Vàng cao quý.", "Đọc khi gặp hoạn nạn và khốn khó nặng nề.", "Nabi ﷺ đọc lời này khi gặp hoạn nạn."),
    )
}
